template.query:
query ProcessMemoryAnalysis {
  systemStats {
    process {
      pid
      cpu
      version
      platform
    }
    memory {
      used
      free
      total
      percentage
      heap {
        used
        total
        external
        arrayBuffers
      }
    }
    timestamp
    uptime
  }

  memoryStats {
    used
    free
    total
    percentage
    heap {
      used
      total
      external
      arrayBuffers
    }
  }
}
